// 1. Setup bpmn-js environment as per SETUP.md
// 2. Download the test diagram from the bug report: https://github.com/bpmn-io/bpmn-js/files/3265424/test.bpmn.txt
// 3. Open the diagram in the modeler:

import BpmnJS from 'bpmn-js/lib/Modeler';
import diagramXML from './test.bpmn'; // Save the test.bpmn.txt as test.bpmn

const bpmnModeler = new BpmnJS({
  container: '#canvas'
});

bpmnModeler.importXML(diagramXML, function(err) {
  if (err) {
    console.error('could not import BPMN 2.0 diagram', err);
  } else {
    console.log('diagram imported successfully');
  }
});

